const fs=require('node:fs');
const path=require('node:path');
const {industries,cases,workflows,formats,providers}=require('./hub-content.cjs');
const faqs=require('./hub-faqs.json');
const dataMedia=require('./data-media.cjs');
function dataEvidenceRow(key,title,copy,{kicker='',level='h3',links=''}={}){return `<div class="data-evidence-row"><div class="data-evidence-copy">${kicker?`<span class="eyebrow">${esc(kicker)}</span>`:''}<${level}>${esc(title)}</${level}>${copy}${links}</div>${dataFigure(key)}</div>`;}
function dataEvidenceSection(id,kicker,title,copy,key,{pale=false,after=''}={}){return `<section class="hub-section ${pale?'pale':''}" id="${id}"><div class="container">${dataEvidenceRow(key,title,copy,{kicker,level:'h2'})}${after}</div></section>`;}
const root=path.resolve(__dirname,'../dist');
const origin='https://griidai-homepage-review.griidai-9992.chatgpt.site';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,url,cls='text-link')=>`<a class="${cls}" href="${esc(url)}">${esc(label)} <span aria-hidden="true">↗</span></a>`;
const button=(label,url,primary=true)=>link(label,url,'button '+(primary?'primary':'secondary'));
const start=()=>button('Start for Free','https://app.griidai.com');
const contact=(label='Talk to Sales',topic='Enterprise')=>button(label,'/contact-sales.html?topic='+encodeURIComponent(topic));
const arrow='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
const navLink=(name,url,current)=>`<a href="${url}"${current===url?' aria-current="page"':''}>${name}</a>`;
function navGroup(name,url,id,items,current){return `<div class="nav-group">${navLink(name,url,current)}<button class="nav-disclosure" aria-label="Open ${name} menu" aria-controls="${id}-submenu" aria-expanded="false">${arrow}</button><div class="nav-submenu" id="${id}-submenu" hidden>${items}</div></div>`;}
function header(current){return `<header><noscript><style>header{height:auto;position:static}.header-inner{flex-wrap:wrap;padding-block:15px}#navigation{position:static;display:flex;flex-wrap:wrap;width:100%;order:4;max-height:none;box-shadow:none;border:0;padding:10px 0}.menu-toggle,.nav-disclosure{display:none!important}</style></noscript><div class="container header-inner"><a class="logo" href="/" aria-label="GriidAi home"><img src="/assets/logo.png" alt="GriidAi" width="172" height="97"></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="Toggle navigation">☰</button><nav id="navigation" aria-label="Main navigation">${navGroup('Platform','/platform/','platform',navLink('Platform Overview','/platform/',current)+navLink('Agentic GeoAI','/agentic-geoai/',current)+navLink('Spatial Analysis','/spatial-analysis/',current)+navLink('Enterprise','/enterprise/',current),current)}${navGroup('Solutions','/solutions/','solutions',`<div><span>By Industry</span>${navLink('All Industries','/industries/',current)}${industries.map(i=>navLink(esc(i.short),'/industries/#'+i.id,current)).join('')}</div><div><span>By Use Case</span>${navLink('All Use Cases','/use-cases/',current)}${cases.map(c=>navLink(esc(c.name),'/use-cases/#'+c.id,current)).join('')}</div>`,current)}${navLink('Data','/data/',current)}${navLink('Workflows','/workflows/',current)}${navLink('Ecosystem','/ecosystem/',current)}${navLink('Pricing','/pricing/',current)}${navLink('About','/about/',current)}</nav><div class="header-actions">${start()}</div></div></header>`;}
const originalHome=fs.readFileSync(path.join(root,'index.html'),'utf8');
const existingFooter=originalHome.match(/<footer[\s>][\s\S]*?<\/footer>/)[0].replace(/<div class="(?:container )?footer-sitemap">[\s\S]*?<\/div><!-- sitemap -->/,'');
function footer(){const sitemap=`<div class="footer-sitemap"><div><span>Explore the platform</span>${link('Platform','/platform/')}${link('Data','/data/')}${link('Workflows','/workflows/')}</div><div><span>Find your application</span>${link('Industries','/industries/')}${link('Use Cases','/use-cases/')}${link('Enterprise','/enterprise/')}</div><div><span>Connect with GriidAi</span>${link('Ecosystem','/ecosystem/')}${link('About','/about/')}${link('Contact Sales','/contact-sales.html')}</div></div><!-- sitemap -->`;return existingFooter.replace('<div class="footer-company">',sitemap+'<div class="footer-company">');}
const paragraphs=txt=>Array.isArray(txt)?txt.map(t=>`<p>${esc(t)}</p>`).join(''):`<p>${esc(txt)}</p>`;
function section(id,kicker,title,body,{pale=false,intro='',cls=''}={}){return `<section class="hub-section ${pale?'pale':''} ${cls}"${id?` id="${id}"`:''}><div class="container"><div class="hub-section-heading"><span class="eyebrow">${esc(kicker)}</span><h2>${esc(title)}</h2>${intro?paragraphs(intro):''}</div>${body}</div></section>`;}
const grid=(items,cols=3)=>`<div class="hub-grid cols-${cols}">${items.join('')}</div>`;
const note=(s)=>`<p class="hub-note">${esc(s)}</p>`;
function card(title,text,extra='',kicker=''){return `<article class="hub-card">${kicker?`<span class="eyebrow">${esc(kicker)}</span>`:''}<h3>${esc(title)}</h3>${paragraphs(text)}${extra}</article>`;}
function table(headers,rows){return `<div class="hub-table-wrap"><table class="hub-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,j)=>`<${j===0?'th scope="row"':'td'} data-label="${esc(headers[j])}">${cell}</${j===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function stepper(items){return `<ol class="hub-steps">${items.map(([name,desc],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(name)}</h3><p>${esc(desc)}</p></div></li>`).join('')}</ol>`;}
const standardSteps=[['Define','State the spatial question, study area, time window and intended use.'],['Data','Bring your own layers or use a supported source. Inspect coverage and metadata.'],['Plan','See the proposed inputs, method, validation and expected output.'],['Review','Check assumptions, units, parameters and the selected data before execution.'],['Execute','Run the approved, supported spatial operations.'],['Validate','Inspect maps, tables, statistics and intermediate results.'],['Continue','Export, refine or carry the result into the next analytical step.']];
function faq(items){return `<div class="hub-faq">${items.map(([q,a])=>`<details><summary>${esc(q)}<span aria-hidden="true">+</span></summary><div>${paragraphs(a)}</div></details>`).join('')}</div>`;}
function jump(items){return `<div class="hub-jump"><div class="container"><details open><summary>On this page ${arrow}</summary><div class="hub-jump-links">${items.map(([name,id])=>`<a href="#${id}">${esc(name)}</a>`).join('')}</div></details></div></div>`;}
function hero(name,title,copy,actions,visual,meta){return `<section class="container hub-hero"><div class="hub-breadcrumbs"><a href="/">Home</a><span aria-hidden="true">/</span><span>${esc(name)}</span></div><div class="hub-hero-grid"><div><span class="eyebrow">${esc(meta||name)}</span><h1>${esc(title)}</h1>${paragraphs(copy)}<div class="actions">${actions}</div></div>${visual}</div></section>`;}
function productFigure(caption){return `<figure class="hub-product"><div class="hub-frame-bar"><i></i><i></i><i></i><span>THE GRIIDAI WORKSPACE</span></div><img src="/assets/homepage-video-poster-1280.webp" srcset="/assets/homepage-video-poster-640.webp 640w, /assets/homepage-video-poster-1280.webp 1280w" sizes="(max-width: 800px) 100vw, 52vw" alt="GriidAi workspace welcome screen with entry points for uploading data, spatial analysis and workflow automation" width="1280" height="720"><figcaption>${esc(caption)}</figcaption></figure>`;}
function dataFigure(key,{hero=false}={}){const media=dataMedia[key];const file=path.join(root,'assets/data',media.file);const bytes=fs.readFileSync(file);const width=bytes.readUInt32BE(16),height=bytes.readUInt32BE(20);const url='/assets/data/'+media.file;return `<figure class="data-product-figure data-figure-${key}${hero?' data-figure-hero':''}"><a class="data-image-link" href="${url}" data-image-viewer data-image-label="${esc(media.label)}" aria-label="Enlarge: ${esc(media.label)}" aria-describedby="data-caption-${key}"><img src="${url}" alt="${esc(media.alt)}" width="${width}" height="${height}" loading="${hero?'eager':'lazy'}" decoding="async"${hero?' fetchpriority="high"':''}><span class="data-enlarge-label" aria-hidden="true">Enlarge image ↗</span></a><figcaption id="data-caption-${key}"><strong>${esc(media.label)}</strong><span>${esc(media.caption)}</span></figcaption></figure>`;}
function methodFigure(title,items){return `<aside class="hub-method-figure"><div class="hub-frame-bar"><span>ILLUSTRATIVE METHOD STRUCTURE</span><span aria-hidden="true">↗</span></div><p class="hub-method-question">${esc(title)}</p>${items.map(([a,b],i)=>`<div class="hub-method-row"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(a)}</strong><p>${esc(b)}</p></div>${i===items.length-1?'<span aria-hidden="true">✓</span>':''}</div>`).join('')}<div class="hub-method-caption">Visible inputs. Reviewable steps. Expert judgment.</div></aside>`;}
function mapArt(kind){const base='<path d="M-30 70 Q100 20 180 90T440 75M-30 150Q110 100 200 165T450 160M-20 235Q100 180 210 245T450 230" stroke="#fff" stroke-width="9" fill="none"/><path d="M70-20L140 290M250-30L280 300M-10 120L430 110" stroke="#f7faf6" stroke-width="5" fill="none"/>';
let shapes=kind===0?'<path d="M80-30Q310 75 175 125T230 300" stroke="#5595a5" stroke-width="7" fill="none"/><path d="M130 70L220 100M185 145L115 190M185 200L285 250" stroke="#5595a5" stroke-width="3"/>':kind===1?'<path d="M65 40L160 65 145 145 60 120ZM180 60L270 40 285 130 200 150ZM60 160L150 180 165 250 80 235ZM205 180L300 165 340 240 235 255Z" fill="#71a67f" stroke="#eef5e9" stroke-width="3"/>':kind===2?'<circle cx="190" cy="145" r="80" fill="#28758820" stroke="#287588" stroke-dasharray="5 6"/><circle cx="280" cy="185" r="62" fill="#28758815" stroke="#287588" stroke-dasharray="5 6"/><circle cx="190" cy="145" r="7" fill="#287588"/><circle cx="280" cy="185" r="7" fill="#287588"/>':'<path d="M-20 240Q120 90 230 150T440 40L440 300H-20Z" fill="#72a4b8" opacity=".75"/><path d="M-20 205Q120 60 230 120T440 10" fill="none" stroke="#287588" stroke-width="2" stroke-dasharray="7 5"/>';
if(kind===4)shapes='<path d="M95 95L220 170 320 85" fill="none" stroke="#287588" stroke-width="2" stroke-dasharray="5 6"/><circle cx="95" cy="95" r="19" fill="#287588"/><circle cx="220" cy="170" r="19" fill="#72a78e"/><circle cx="320" cy="85" r="19" fill="#91b49c"/><circle cx="95" cy="95" r="28" fill="none" stroke="#287588" stroke-width="2"/><text x="91" y="99" font-size="12" fill="white" font-family="Arial">A</text><text x="216" y="174" font-size="12" fill="white" font-family="Arial">B</text><text x="316" y="89" font-size="12" fill="white" font-family="Arial">C</text>';
return `<svg class="hub-map-art" viewBox="0 0 420 280" role="img" aria-label="Illustrative ${['terrain','vegetation','coverage','coastal','location comparison'][kind]} analysis diagram"><rect width="420" height="280" fill="#e6ecdf"/>${base}${shapes}<g fill="#b1b9a6" stroke="#fff" stroke-width="2"><path d="M305 60h28v22h-28zM88 88h26v20H88zM320 190h30v22h-30zM170 210h22v25h-22z"/></g><text x="18" y="263" font-size="9" fill="#365d5f" font-family="Arial">ILLUSTRATIVE • NOT A MEASURED RESULT</text></svg>`;}
function finalCTA(id,title,copy,actions){return `<section class="hub-closing" id="${id}"><div class="container"><span class="eyebrow">YOUR NEXT SPATIAL QUESTION</span><h2>${esc(title)}</h2>${paragraphs(copy)}<div class="actions">${actions}</div></div></section>`;}
function reliability(){return `<div class="hub-split"><div><h3>AI proposes the work. Experts control what proceeds.</h3><p>A plausible map can still be wrong when the projection, time window, units, selected data or analytical assumption is wrong. Review the plan before processing and validate the mapped or tabular result before using it.</p>${link('Explore Agentic GeoAI','/agentic-geoai/')}</div><div class="hub-review-list">${[['Inputs','Are these the intended datasets, geography and time period?'],['Method','Do the operations, units and parameters answer the question?'],['Validation','What checks should pass before accepting the output?'],['Output','Is the result fit for its intended use, or does it need deeper review?']].map(([a,b])=>`<div><span aria-hidden="true">✓</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div></div>`;}
function workflowLinks(ids=workflows.map(w=>w.id)){return grid(ids.map(id=>{const w=workflows.find(w=>w.id===id);return card(w.name,w.question,`<p class="hub-small"><strong>Inputs:</strong> ${esc(w.input)}</p>${link('Explore example method','/workflows/#'+w.id)}`,'EXAMPLE · '+w.domain);}),ids.length===2?2:3);}
function caseLinks(ids=cases.map(c=>c.id)){return grid(ids.map(id=>{const c=cases.find(x=>x.id===id);return card(c.name,c.question,link('Explore this use case','/use-cases/#'+c.id),c.pattern);}),ids.length===4?2:3);}
function industryLinks(){return grid(industries.map(i=>card(i.name,i.question,link('Explore industry context','/industries/#'+i.id))),2);}
function filterControls(id,options,placeholder){return `<form class="hub-filters" data-filter-for="${id}" role="search" hidden><div class="hub-search-field"><label for="${id}-search">Search ${id==='format-list'?'formats':id==='case-list'?'use cases':'workflows'}</label><input id="${id}-search" name="q" type="search" placeholder="${esc(placeholder)}" autocomplete="off"></div>${options.map(([label,name,values])=>`<div><label for="${id}-${name}">${label}</label><select id="${id}-${name}" name="${name}"><option value="">All ${label.toLowerCase()}</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div>`).join('')}<button class="button secondary hub-clear" type="reset">Clear filters</button><p class="hub-filter-count" aria-live="polite" aria-atomic="true"></p></form>`;}
function noResults(id){return `<div class="hub-empty hub-no-results" data-empty-for="${id}" hidden><h3>No ${id==='format-list'?'formats':id==='case-list'?'use cases':'workflows'} match these filters.</h3><p>Try another search or clear a filter to explore the full collection.</p><button class="button secondary" data-reset="${id}">Clear filters</button></div>`;}

function dataPage(){const formatCards=formats.map(f=>`<article class="hub-format hub-filter-item" data-family="${esc(f.family)}" data-search="${esc([f.name,f.extensions,f.family].join(' '))}"><details id="format-${f.id}" class="hub-record"><summary><div><span class="hub-tag">${esc(f.family)}</span><h3>${esc(f.name)}</h3><span class="hub-small">${esc(f.extensions)}</span></div><span class="hub-record-action">Handling notes <b aria-hidden="true">+</b></span></summary><div class="hub-record-body">${paragraphs(f.note)}<dl class="hub-direction-list">${['upload','inspect','analyze','export'].map(d=>`<div><dt>${d}</dt><dd>${f[d]}</dd></div>`).join('')}</dl><p class="hub-small">Compatibility verification date: not published.</p>${link('Discuss this format','/contact-sales.html?topic='+encodeURIComponent(f.name+' compatibility'))}</div></details></article>`).join('');
return hero('Data','Geospatial data, connected to the analysis you need.','Start with data you already have or work with supported geospatial sources inside GriidAI. Bring vector, raster, tabular, and multidimensional data into the workspace, review its context, and use it directly in an AI-guided spatial analysis workflow.',button('Explore Data Sources','#data-sources')+button('Bring Your Own Data','#bring-your-data',false),dataFigure('upload',{hero:true}),'DATA / FROM SOURCE TO SPATIAL EVIDENCE')+
jump([['Discover','discover-data'],['Your data','bring-your-data'],['Sources','data-sources'],['Formats','supported-formats'],['Workflows','data-workflows'],['Workspace','data-workspace'],['Readiness','data-readiness'],['FAQs','data-faq']])+
section('data-definition','THE STARTING POINT','What geospatial data can I use in GriidAI?',`<div class="hub-reading">${paragraphs(['GriidAI supports two data paths. You can upload supported geospatial files from your own work, or use supported external and public sources when the required access path is available. Once data is in the workspace, inspect it, select it as an input, and use it in supported analysis, mapping, and later workflow steps.','Use the source directory and format guidance on this page to check access requirements and handling notes. The right input also depends on your study area, time period, variables and analytical method.'])}</div>`)+
section('data-paths','01 / TWO WAYS TO START','Start with a trusted source or bring the data you already use.',grid([card('Discover supported data','Use a supported source and narrow the request by area, time, variable or analytical need. Check the source and review the acquisition step before continuing.',link('Explore Data Sources','#data-sources'),'DISCOVER'),card('Bring your own data','Upload supported files, inspect their spatial context, and use the intended dataset in a reviewed analysis.',link('Bring Your Own Data','#bring-your-data'),'UPLOAD')],2),{pale:true})+
section('discover-data','02 / DATA DISCOVERY','Find data in the context of the analysis.',`<div class="hub-split"><div>${paragraphs(['When the required source is supported, GriidAI can use the study area and analytical intent to locate or fetch relevant geospatial data, make it available in the workspace, and continue into the next analytical step.','Review the selected source, area and time coverage before continuing. Data from different sources may represent different measurements, resolutions or methods.'])}${link('Browse Sources','#data-sources')}</div>${methodFigure('Make the data request specific.',[['Area','Define the study area or AOI.'],['Time & variable','State the period and the measurement you need.'],['Scale & source','Check resolution, source type and access.'],['Review','Inspect the retrieval plan before continuing.']])}</div>`)+
dataEvidenceSection('bring-your-data','03 / YOUR PROJECT INPUTS','Use the data your project already depends on.',paragraphs(['Upload supported geospatial data into the GriidAI workspace, organize it in the Data Catalog, inspect the map and metadata, and use the dataset as input to your next prompt or analysis step.','Keep the uploaded layer connected to the map, its attributes and the next analytical question.']), 'catalog',{pale:true,after:`${stepper(standardSteps)}<div class="hub-callout"><h3>From an uploaded layer to a reviewed operation</h3><p>Upload building footprints, select the intended feature, and review a 50-meter buffer operation before execution. Inspect the buffer and a follow-on intersection result to identify nearby or overlapping buildings.</p><p class="hub-small">Illustrative method: confirm metric distance handling, the intended input and a suitable projected CRS before processing.</p>${link('Check Supported Formats','#supported-formats')}</div>`})+
section('data-sources','04 / SOURCE DIRECTORY','Explore geospatial data sources',`${paragraphs('Source access can depend on the dataset, geography, provider account, credentials, subscription or license. Public access does not mean unrestricted redistribution.')}<div class="hub-empty"><span class="hub-tag">SOURCE INVENTORY</span><h3>Current source details are not available here yet.</h3><p>You can explore supported upload options below, or contact us about a particular source and your requirements.</p><div class="actions">${button('Explore upload options','#supported-formats')}${contact('Ask about a source','Data source inquiry')}</div></div>${note('A provider is the organization or service. A dataset is a particular product, collection or layer; access and coverage may differ between products from the same provider.')}`)+
section('supported-formats','05 / DATA TYPES & FILES','Check your format from input to output',`${paragraphs('Upload, inspection, analysis and export are separate capabilities. A file accepted as an input may not be available as an output, and analysis depends on its structure and the selected operation.')}${grid([card('Vector','Discrete features with geometry and attributes: points, lines, polygons, buildings, roads and boundaries.'),card('Raster','Cell-based grids and imagery, including elevation, land cover and satellite imagery.'),card('Tabular & multidimensional','Rows and fields, or supported variables and slices across dimensions such as time or depth.')],3)}<div class="hub-callout"><h3>Format handling reference</h3><p>The notes below explain what to check when preparing a file. Direction-specific compatibility and verification dates are not published here yet. Confirm the current upload, analysis and export path in the app or with our team.</p></div>${filterControls('format-list',[['Family','family',[...new Set(formats.map(f=>f.family))]]],'GeoTIFF, .shp, Zarr…')}<div class="hub-format-list" id="format-list">${formatCards}</div>${noResults('format-list')}`,{pale:true})+
section('data-workflows','06 / CONNECT DATA TO A METHOD','Use the dataset in a method you can review',`${paragraphs('Data becomes useful when it stays connected to the method. Review the selected inputs, follow supported analytical steps, inspect intermediate and final results, and continue or export when the next task requires it.')}${workflowLinks(['dem-hydrology-stream-network','ndvi-analysis','fire-station-coverage'])}${link('Explore all Workflows','/workflows/')}`)+
section('data-workspace','07 / WORKSPACE CONTEXT','Keep data, intermediate outputs, and analysis context in one workspace.',`<div class="hub-split"><div>${paragraphs(['The Data Catalog is the working inventory for a GriidAI session. Uploaded and acquired datasets can be organized, viewed on the map, inspected in tables or metadata panels, selected as prompt inputs, and carried through multi-step analysis.','Use attribute tables to examine vector records and metadata views to check the available structural and spatial information. Select the exact workspace layer for the next question so similarly named datasets do not create ambiguity.'])}${link('Explore the Platform','/platform/')}</div><div class="hub-review-list">${[['Source data','Keep the original project inputs understandable.'],['Intermediate results','Inspect temporary outputs without confusing them with final layers.'],['Map & metadata','Check visibility, attributes, spatial reference and raster context.'],['Next analysis','Select the intended layer before generating the next plan.']].map(([a,b])=>`<div><span aria-hidden="true">↳</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div></div>`,{pale:true})+
dataEvidenceSection('data-readiness','08 / READY FOR THE QUESTION','Know what the data represents before you use it',paragraphs('Confirm the intended dataset and study area, inspect its geometry or raster structure, and check spatial reference, units and missing-value behavior. Define any preparation needed before using the data in a reviewed method.')+note('Data preparation is an explicit, reviewed action. Do not assume that every uploaded file is automatically cleaned or corrected.'),'metadata',{after:`<div class="data-readiness-checks">${grid([card('Source, area & time','Check where the data came from, its license, where and when it applies, and whether it represents observations, estimates, forecasts or modeled conditions.'),card('CRS, scale & units','Check coordinate systems, distance and area units, resolution, grid alignment and the level of detail the decision requires.'),card('Fields, dimensions & NoData','Inspect geometry, attributes, duplicates, variables, bands, missing values and masks. A successful upload does not guarantee analytical suitability.')])}</div>`})+
section('data-reuse','09 / CONTINUE THE WORK','Keep the result usable after the analysis.',`<div class="data-export-rows">${dataEvidenceRow('datasetExport','Take the analytical dataset into the next step.',paragraphs('Inspect the result, then export a supported analytical dataset when the next task requires reusable GIS data. Check the available format and the exported file details before continuing.'),{links:link('Check format handling','#supported-formats')})}${dataEvidenceRow('mapExport','Share the map with its context.',paragraphs('A map image communicates the view you have prepared. Include its legend and choose PNG, JPEG or PDF from the map export controls.'),{links:link('Explore maps and outputs','/platform/#outputs')})}</div><div class="hub-callout"><h3>Reuse the intended inputs</h3><p>Where session data sharing is available, reuse trusted datasets in another session and continue with the same project inputs. Check current sharing behavior; this does not imply real-time co-editing.</p>${link('See the workspace','/platform/#workspace')}</div>`,{pale:true})+
section('data-faq','QUESTIONS ABOUT DATA','A little context before you start',faq(faqs.data))+
finalCTA('data-next-step','Start with the data your question needs.','Find a supported source or bring your own dataset. Check its context, review the method, and move into spatial analysis with GriidAI.',start()+button('Bring Your Own Data','#bring-your-data',false));}

function industriesPage(){return hero('Industries','Geospatial intelligence built around the decisions your industry makes.','GriidAi connects geospatial data, spatial analysis, AI-guided execution, human review, maps, and reusable outputs in one workspace. Explore how that workflow applies to environmental projects, climate and physical risk, infrastructure, and location-based business decisions.',button('Explore Your Industry','#industry-directory')+button('Start for Free','https://app.griidai.com',false),`<aside class="hub-industry-mosaic">${industries.map((i,n)=>`<a href="#${i.id}"><div>${mapArt([0,3,2,4][n])}</div><span><small>0${n+1} / INDUSTRY</small><strong>${esc(i.short)}</strong><b aria-hidden="true">↗</b></span></a>`).join('')}</aside>`,'INDUSTRIES / ONE PLATFORM. DIFFERENT DECISIONS.')+
jump([['Industries','industry-directory'],['Decision matrix','decision-matrix'],['How it works','how-it-works'],['Use cases','industry-use-cases'],['Workflows','industry-workflows'],['Enterprise','industry-enterprise']])+
section('industry-directory','01 / FIND YOUR CONTEXT','Explore GriidAi by industry',`<div class="hub-grid cols-2">${industries.map((i,n)=>`<article class="hub-industry-card" id="${i.id}"><div class="hub-industry-card-top"><span class="eyebrow">0${n+1} / ${esc(i.short)}</span><span aria-hidden="true">↗</span></div><h3>${esc(i.name)}</h3>${paragraphs(i.description)}<details><summary>Explore the spatial questions <b aria-hidden="true">+</b></summary><div>${paragraphs(i.question)}<dl><dt>Analysis families</dt><dd>${esc(i.analysis)}</dd><dt>Outputs to inspect</dt><dd>${esc(i.output)}</dd></dl></div></details><div class="hub-card-links">${i.cases.map(id=>link(cases.find(c=>c.id===id).name,'/use-cases/#'+id)).join('')}</div></article>`).join('')}</div>`,{intro:'Start with the environment in which the decision is made. Explore the questions, data, methods and outputs that matter in your sector.'})+
section('shared-pattern','02 / A CONNECTED WAY OF WORKING','Different industries. A familiar geospatial pattern.',`${paragraphs(['Environmental consultants, resilience teams, utilities, and location-intelligence teams ask different business questions, but the work often repeats the same underlying pattern: find or bring the right data, prepare it, run spatial analysis, check assumptions, review the result, and communicate what the map means for the decision.','GriidAi is designed to connect those steps so expert methods do not have to be rebuilt from scratch for every new project or location.'])}<div class="hub-flow-line">${['Question','Data','Analysis','Review','Result','Reuse'].map((t,n)=>`<span><small>0${n+1}</small>${t}</span>`).join('')}</div>`,{pale:true})+
section('decision-matrix','03 / QUESTIONS & EVIDENCE','See the kinds of spatial questions GriidAi can support',table(['Industry','Typical question','Analysis families','Outputs to inspect'],industries.map(i=>[esc(i.short),esc(i.question),esc(i.analysis),esc(i.output)]))+note('These are decision patterns. The examples illustrate analytical methods; they do not imply that every scenario is a packaged, one-click workflow.'))+
section('how-it-works','04 / FROM QUESTION TO RESULT','Keep the industry context. Keep the expert in control.',`${paragraphs('Industry context changes the data, assumptions, thresholds and interpretation of a spatial analysis. GriidAi can help organize and execute supported steps, while the expert reviews the plan and validates the outcome before it informs a decision.')}${stepper(standardSteps)}${link('See How GriidAi Works','/platform/#how-it-works')}`,{pale:true})+
section('industry-use-cases','05 / CROSS-INDUSTRY QUESTIONS','Common decisions across industries',caseLinks()+link('Explore All Use Cases','/use-cases/'))+
section('industry-workflows','06 / METHODS IN CONTEXT','See industry questions become spatial workflows',workflowLinks(['dem-hydrology-stream-network','fire-station-coverage','sea-level-rise'])+link('Explore the Workflow Library','/workflows/'),{pale:true})+
section('industry-review','07 / HUMAN-GUIDED RELIABILITY','Spatial decisions need more than a plausible map',reliability())+
section('industry-enterprise','08 / YOUR WAY TO START','Start with one workflow. Scale the methods that prove useful.',grid([card('For professionals','GIS professionals, consultants, researchers and adjacent analysts can start with their own data, questions and supported workflows.',start()+link('Explore Workflows','/workflows/'),'START WITH YOUR QUESTION'),card('For enterprise teams','Bring a bounded, repeated spatial question. Evaluate the data, expert review and outputs first, then discuss integration, governance and deployment requirements.',contact()+link('Explore Enterprise','/enterprise/'),'PROVE A REPEATABLE METHOD')],2),{pale:true})+
finalCTA('industry-next-step','Find the industry path that matches your next spatial decision.','Explore an industry, open a relevant method, or start with your own geospatial question.',start()+contact());}

function useCasesPage(){return hero('Use Cases','Start with the spatial question. Build the analysis around it.','Explore common geospatial questions—from choosing a site and identifying a coverage gap to understanding flood exposure, drainage patterns or vegetation condition. GriidAi helps connect the question to data, supported spatial analysis, human review and usable outputs.',button('Explore a Use Case','#use-case-library')+button('Start for Free','https://app.griidai.com',false),methodFigure('What do you need to understand?',[['Compare locations','Which candidate sites deserve deeper review?'],['Find gaps','Where is coverage insufficient?'],['Assess scenarios','Which assets may be exposed?'],['Measure change','What does the imagery reveal?']]),'USE CASES / QUESTION FIRST. METHOD VISIBLE.')+
jump([['Explore','use-case-library'],['The process','case-process'],['Data & method','case-data'],['Review','case-review'],['Industries','case-industries'],['Enterprise','case-enterprise']])+
section('case-definition','THE TASK BEHIND THE MAP','What is a geospatial use case?',`<div class="hub-reading">${paragraphs(['A geospatial use case is a real-world question that depends on location, distance, spatial relationships, terrain, environmental conditions, networks or change over space. The answer usually requires a combination of data, GIS operations, assumptions, validation and a map or analytical output—not just a single GIS tool.','In GriidAi, the user defines the question, brings or discovers relevant data, reviews the proposed plan, approves supported analysis, validates the result and decides how the output should be used.'])}</div>`)+
section('use-case-library','01 / FIND YOUR QUESTION','Choose the question you need to answer',`${filterControls('case-list',[['Decision pattern','pattern',[...new Set(cases.map(c=>c.pattern))]]],'Site selection, exposure, vegetation…')}<div class="hub-case-list" id="case-list">${cases.map((c,n)=>`<article class="hub-case-record hub-filter-item" data-pattern="${esc(c.pattern)}" data-search="${esc([c.name,c.question,c.description,c.pattern,...c.industries.map(i=>industries[i].name)].join(' '))}" id="${c.id}"><div class="hub-case-heading"><span class="hub-case-number">0${n+1}</span><div><span class="eyebrow">${esc(c.name)} / ${esc(c.pattern)}</span><h3>${esc(c.question)}</h3><p>${esc(c.description)}</p><div class="hub-tags">${c.industries.map(i=>`<a class="hub-tag" href="/industries/#${industries[i].id}">${esc(industries[i].short)}</a>`).join('')}</div></div></div><details><summary>Data, method & outputs <b aria-hidden="true">+</b></summary><div class="hub-case-body"><h4>${esc(c.detailTitle)}</h4><dl><dt>Typical inputs</dt><dd>${esc(c.inputs)}</dd><dt>Result to inspect</dt><dd>${esc(c.output)}</dd><dt>Review point</dt><dd>${esc(c.check)}</dd></dl><div class="hub-card-links">${c.workflows.length?c.workflows.map(id=>link('Explore '+workflows.find(w=>w.id===id).name+' example','/workflows/#'+id)).join(''):link('Explore Location & Portfolio context','/industries/#location-intelligence')}${link('Bring Your Own Data','/data/#bring-your-data')}</div></div></details></article>`).join('')}</div>${noResults('case-list')}`,{pale:true,intro:'Start from the task your team recognizes. Explore the question, the spatial evidence involved and the output an expert should inspect.'})+
section('case-process','02 / CONNECT THE STEPS','From a spatial question to a result you can inspect',stepper(standardSteps)+link('See the Platform','/platform/'))+
section('case-patterns','03 / ANOTHER WAY TO EXPLORE','Think in decision patterns',grid([['Screen','Narrow a set to locations that meet explicit spatial conditions.','site-selection'],['Compare','Apply one reviewed method across alternatives or a portfolio.','site-selection'],['Measure','Quantify distance, overlap, elevation or index values.','vegetation'],['Find gaps','Identify where service, access or coverage is weak.','coverage'],['Understand terrain / flow','Derive terrain and drainage context from elevation.','hydrology'],['Assess scenarios','Compare locations with a defined external scenario.','flood-coastal']].map(([a,b,id])=>card(a,b,link('Explore the question','#'+id))),3),{pale:true})+
section('case-workflows','04 / GO DEEPER INTO THE METHOD','Explore the analysis behind the question',workflowLinks(['dem-hydrology-stream-network','ndvi-analysis','fire-station-coverage'])+link('Explore All Workflows','/workflows/'))+
section('case-data','05 / DATA + METHOD','The same question can produce a different answer when the data or method changes',grid([card('Coverage & time','A historical observation, forecast, scenario and current snapshot are different kinds of evidence. Confirm geographic and temporal coverage.'),card('Resolution & spatial reference','Scale, CRS, distance units, raster alignment and missing values affect the result. Absence of data is not automatically zero.'),card('Thresholds & rights','Make distance, scenario and scoring assumptions visible. Check licensing and attribution before exporting or publishing.')])+link('Explore Data & Formats','/data/'),{pale:true})+
section('case-review','06 / EXPERT CONTROL','AI can help organize the analysis. Experts still control the method and result.',reliability())+
section('case-industries','07 / SECTOR CONTEXT','The same use case changes meaning across industries',industryLinks(),{pale:true,intro:'The criteria, data and decision boundary change with the sector. Follow the question into the industry context that fits your work.'})+
section('case-enterprise','08 / FROM TASK TO TEAM METHOD','Turn a recurring spatial question into a repeatable team capability',`<div class="hub-reading">${paragraphs('Start with one bounded, repeated question and a clear owner. Prove that the inputs, supported operations, review points and outputs fit the decision before discussing wider organizational requirements.')}<div class="actions">${button('Explore Enterprise','/enterprise/')}${contact('Discuss Your Workflow')}</div></div>`)+
finalCTA('case-next-step','Bring the question. Keep the method visible.','Start with your own data and a spatial question, or explore an example before you begin.',start()+button('Explore Workflows','/workflows/',false));}

function workflowsPage(){return hero('Workflows','Automate multi-step GIS workflows with GriidAi.','Explore geospatial workflow examples that connect data, an inspectable execution plan, supported GIS operations, human review, validation, maps, and analytical outputs. Start from a spatial question, see the method, and inspect the result before it moves into the next decision.',button('Explore a Workflow','#workflow-library')+button('Start for Free','https://app.griidai.com',false),methodFigure('How can I derive drainage patterns from elevation?',[['Data','DEM + study area'],['Plan','Prepare → flow → stream extraction'],['Review','Check units, resolution and thresholds'],['Result','Inspect layers, map and drainage context']]),'WORKFLOWS / THE QUESTION. THE METHOD. THE RESULT.')+
jump([['Browse','workflow-library'],['How it works','workflow-process'],['Validation','workflow-validation'],['Data & outputs','workflow-data'],['Repeatability','workflow-reuse'],['FAQs','workflow-faq']])+
section('workflow-definition','MORE THAN A PROMPT','What is a GriidAi geospatial workflow?',`<div class="hub-reading">${paragraphs(['A GriidAi workflow is an ordered sequence that connects a spatial question to the data, GIS operations, validation checkpoints and outputs needed to answer it. For supported tasks, GriidAi can propose the implementation plan, let the user review the inputs and method, execute the approved analysis, and keep resulting layers, maps, tables or statistics available for inspection.','A workflow is more than a prompt and more than a single GIS tool. It should make the method visible enough for an expert to review what was used, what assumptions matter, what result was produced and whether the output is fit for the intended decision.'])}</div>`)+
section('workflow-library','01 / THE WORKFLOW LIBRARY','Five questions. Five inspectable methods.',`${note('These are reference examples of analytical methods, not a promise of packaged one-click execution. Use your own suitable inputs, confirm available operations in the app, and review the plan and result.')}${filterControls('workflow-list',[['Domain','domain',[...new Set(workflows.map(w=>w.domain))]],['Data type','type',['Raster','Mixed']],['Status','status',['Example']]],'Hydrology, NDVI, coverage…')}<div id="workflow-list" class="hub-workflow-list">${workflows.map((w,n)=>`<article class="hub-workflow-record hub-filter-item" data-domain="${esc(w.domain)}" data-type="${w.type}" data-status="${w.status}" data-search="${esc([w.name,w.question,w.domain,w.input,...w.industries.map(i=>industries[i].name)].join(' '))}"><div class="hub-workflow-preview">${mapArt(n>2?3:n)}<span class="hub-tag">${w.status}</span></div><div class="hub-workflow-copy"><span class="eyebrow">0${n+1} / ${esc(w.domain)}</span><h3>${esc(w.name)}</h3><p class="hub-workflow-question">${esc(w.question)}</p><p>${esc(w.description)}</p><div class="hub-input"><span>INPUTS</span>${esc(w.input)}</div><details id="${w.id}" class="hub-record"><summary>Explore the example method <b aria-hidden="true">+</b></summary><div class="hub-record-body"><ol class="hub-method-steps">${w.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><dl><dt>Result to inspect</dt><dd>${esc(w.output)}</dd><dt>Validation & limits</dt><dd>${esc(w.validation)}</dd></dl><p class="hub-small">Reference example · current production verification date not published.</p><div class="hub-card-links">${link('Explore '+cases.find(c=>c.id===w.related).name,'/use-cases/#'+w.related)}${link('Check input formats','/data/#supported-formats')}${link('Start with your own inputs','https://app.griidai.com')}</div></div></details></div></article>`).join('')}</div>${noResults('workflow-list')}`,{pale:true})+
section('workflow-process','02 / INSIDE A WORKFLOW','See the method before the result',stepper(standardSteps)+link('See How the Platform Works','/platform/#how-it-works'))+
section('workflow-validation','03 / HUMAN-GUIDED RELIABILITY','AI can propose the workflow. The expert still validates the method and result.',reliability(),{pale:true})+
section('workflow-data','04 / INPUTS. OPERATIONS. OUTPUTS.','Every workflow should make its dependencies understandable.',grid([card('Data with context','Identify the input layers, study area, time period and required variables. Check source rights and the actual access path.',link('Explore Data','/data/'),'01 / INPUTS'),card('Supported operations','A workflow combines GIS operations in an ordered method. A buffer, raster calculation or flow operation is a step, rather than the whole use case.',link('Explore Spatial Analysis','/spatial-analysis/'),'02 / METHOD'),card('Inspectable results','Review analytical layers, a map with meaningful legend, attributes, tables and statistics. Choose a supported analytical export or map output for the next task.',link('Check Format Handling','/data/#supported-formats'),'03 / OUTPUTS')]))+
section('workflow-reuse','05 / REPEATABILITY','Keep the successful method connected to the next question.',`<div class="hub-reading">${paragraphs(['GriidAi is designed to turn successful analytical methods into repeatable geospatial work. Continue from available session context, use trusted project data, and follow a published method where the current product supports those steps.','A reference method explains inputs, assumptions, steps and validation. It does not by itself establish a visual workflow builder, automatic version control or a one-click reusable product.'])}${link('Discuss a repeated team workflow','/enterprise/')}</div>`,{pale:true})+
section('workflow-status','06 / READ THE EXAMPLE','What do workflow status labels mean?',grid([card('Example','A reference method or demonstrated sequence. It is not necessarily packaged for one-click execution.'),card('Beta','A publicly available workflow with stated maturity or scope limits, when specifically approved and labeled.'),card('Live','A current workflow available for its stated use, with verified method, supported inputs and current product evidence.')])+note('The collection above currently contains Example records. No Live or Beta availability is inferred from a method description.'))+
section('workflow-faq','WORKFLOW QUESTIONS','Know what to review before you run',faq([
['How can I automate a multi-step GIS workflow?','Define the question, bring or discover relevant data, inspect the proposed plan, approve supported operations, then review maps and analytical outputs. Validate the result before exporting or continuing.'],
['Can I use my own data?','Supported uploaded data can become a workflow input. Inspect its structure, spatial reference, units and coverage, and choose the intended layer before reviewing the plan.'],
['Can a workflow combine raster and vector data?','Supported methods may combine raster and vector operations. Each input and operation still needs to be appropriate for the task; check alignment, scale and the proposed method.'],
['Can I review a workflow before it runs?','For supported executed tasks, the implementation plan exposes Inputs, Method, Validation and Output for user review before processing.'],
['Can I reuse these examples?','Use them as reference methods with suitable inputs and current supported operations. A published example does not imply that a saved, one-click workflow or a visual editor is available.'],
['Does GriidAi replace GIS experts?','No. Experts define the intent, review the method and validate whether the result is appropriate for its intended use.']
]),{pale:true})+
finalCTA('workflow-next-step','Start from a question. Follow the method. Inspect the result.','Explore a reference workflow with your own suitable inputs, or discuss a repeated workflow for your team.',start()+contact('Discuss Your Workflow'));}

const interest=(p='',i='')=>'/ecosystem/express-interest/'+(p?'?path='+p+(i?'&interest='+i:''):'');
function ecosystemPage(){const pathChoices=[['Build','Contributors','Create tools and reusable geospatial workflows. Share your expertise and explore how your work could support other GriidAI users.','contributors'],['Educate','Education & Research','Bring geospatial AI into teaching, student projects, research, workshops, and institutional learning.','education-research'],['Grow','Community & Growth','Share knowledge, engage communities, recommend GriidAI, or introduce relevant business opportunities.','community-growth'],['Sell & Deliver','Solution & Reseller','Help organizations adopt GriidAI through services, implementation, integration, training, support, or local sales.','solutions-resellers']];
return hero('Ecosystem','GriidAI Partner Ecosystem','Build tools, advance learning, grow communities, or bring geospatial AI to organizations. Explore ways to contribute your expertise, collaborate with GriidAI, and create value through geospatial analysis.',button('Express Interest',interest())+button('Explore Four Paths','#participation-paths',false),`<aside class="hub-ecosystem-orbit"><div class="hub-orbit-label"><span class="eyebrow">YOUR EXPERTISE. A SHARED DIRECTION.</span><p>Different ways<br>to make an impact.</p></div>${pathChoices.map(([a,b,,id],n)=>`<a href="#${id}"><span>0${n+1}</span><strong>${esc(a)}</strong><small>${esc(b)}</small><b aria-hidden="true">↗</b></a>`).join('')}</aside>`,'ECOSYSTEM / CONNECT YOUR EXPERTISE')+
jump([['Four paths','participation-paths'],['Contributors','contributors'],['Education','education-research'],['Community','community-growth'],['Solutions','solutions-resellers'],['Choose a route','choose-your-route'],['FAQs','ecosystem-faq']])+
section('ecosystem-definition','PEOPLE. KNOWLEDGE. PRACTICAL VALUE.','What is the GriidAI ecosystem?',`<div class="hub-reading">${paragraphs(['The GriidAI ecosystem brings together people and organizations interested in extending how geospatial AI is built, taught, shared, and applied. It connects technical contributions, education and research, community participation, and customer-facing partnerships around the GriidAI platform.','The four paths describe different ways to participate. You can express interest in more than one and discuss the right fit with the GriidAI team.'])}</div>`)+
section('participation-paths','01 / FIND YOUR PLACE','Find your place in the ecosystem',grid(pathChoices.map(([a,b,c,id])=>card(b,c,link('Explore '+a,'#'+id),a)),2),{pale:true,intro:'Choose a path to explore who it is for, how you could participate, and the opportunities it can open.'})+
section('contributors','02 / BUILD','Build with GriidAI',`<div class="hub-split"><div>${paragraphs(['Contribute practical geospatial knowledge through tools and reusable workflows. If you have a useful analytical method, a repeatable sequence of GIS operations, or a tool that could help others solve spatial problems, tell us what you would like to build or share.','This path is for GIS practitioners, developers, data and AI engineers, researchers, and domain specialists. You can start with an existing contribution or a well-defined idea.'])}${button('Express Interest',interest('contributors'))}</div>${methodFigure('Turn expertise into a contribution.',[['Tools','A focused operation or utility for a clear task.'],['Reusable workflows','An ordered method others could adapt.'],['Documentation','Inputs, outputs, checks and known limitations.']])}</div><div class="hub-callout"><h3>Explore how your work could reach relevant users.</h3><p>Discuss publication, verification or commercial opportunities. Sharing an idea starts a review conversation; publication, verification and monetization are not automatic outcomes.</p></div>`)+
section('education-research','03 / EDUCATE','Bring geospatial AI into education and research',`${paragraphs(['Explore how GriidAI could support teaching, student projects, research, workshops, and institutional learning. Connect spatial questions with data, analytical steps, and results that learners and researchers can inspect and discuss.','This path is for educators, researchers, universities, colleges, training providers, student groups, and individuals developing their geospatial skills.'])}${grid([card('Teaching & workshops','Introduce geospatial AI through guided demonstrations, exercises and discussion of analytical methods.'),card('Projects & research','Explore a defined spatial question, evaluate a method and communicate inputs, process and interpretation.'),card('Institutional learning','Discuss how a department, training provider or organization could include GriidAI in its learning activities.')])}<div class="actions">${button('Express Interest',interest('education_research'))}</div>${note('Product access, resources and support depend on the project and agreed scope. Education participation does not require you to act as a salesperson or content promoter.')}`,{pale:true})+
section('community-growth','04 / GROW','Share expertise and connect opportunities',`${paragraphs('Help more people discover where GriidAI can be useful. Community participation, content-led recommendations and business introductions involve different expectations and reward arrangements.')}${grid([
card('Ambassador',['Share knowledge and support the community through teaching, content, mentoring, feedback and geospatial AI discussions.','The focus is contribution, recognition and collaboration. Access, activity support or compensation is agreed for the role; it is not a commission for each signup.'],link('Explore Ambassador participation',interest('community_growth','ambassador')),'COMMUNITY & KNOWLEDGE'),
card('Affiliate',['Recommend GriidAI through content to audiences that may benefit from the platform. This route is designed around tracked recommendations that lead to eligible paid subscriptions.','Tracking, qualifying subscriptions, commission rates and payment arrangements are confirmed under agreed terms before participation begins.'],link('Express Affiliate interest',interest('community_growth','affiliate')),'CONTENT & RECOMMENDATIONS'),
card('Referral Partner',['Introduce a relevant business opportunity through your professional network. Consultants, advisors, integrators and complementary vendors may help with a qualified introduction and discovery.','GriidAI or the appropriate reseller manages the sale and customer relationship. Any reward depends on an accepted opportunity and agreed terms.'],link('Express Referral interest',interest('community_growth','referral_partner')),'QUALIFIED INTRODUCTIONS')
])}`)+
section('solutions-resellers','05 / SELL & DELIVER','Bring GriidAI to organizations',`${paragraphs('Help organizations apply geospatial AI through professional services, implementation, integration, training, support or local sales. This path is for consultancies, system integrators, geospatial service firms and commercial partners with relevant customer relationships and delivery capability.')}${grid([card('Deliver expertise around the platform','Describe the services you can provide: use-case scoping, workflow development, integration, onboarding, training or ongoing support. Discuss independent services or a closer collaboration.',link('Express Solution Delivery interest',interest('solutions_resellers','solution_delivery'))),card('Carry the commercial relationship','Reselling involves agreed responsibilities for sales, local contracting, billing, first-line support and renewals—a deeper operational commitment than making an introduction.',link('Express Reseller interest',interest('solutions_resellers','reseller')))],2)}${note('Technical enablement, joint opportunities, marketing and commercial arrangements depend on the role, market and agreed scope. You can express interest in services, reselling or both.')}${link('Only making an introduction? Explore Referral Partners','#community-growth')}`,{pale:true})+
section('partner-value','06 / THE VALUE OF WORKING TOGETHER','Explore the value of working together',grid([card('Product & technical guidance','Discuss access and technical guidance relevant to your contribution, learning activity or customer engagement.'),card('Learning & practical resources','Explore materials that help you understand and explain the platform in your own context.'),card('Recognition & visibility','Discuss opportunities to share relevant work, experience or contributions.'),card('Collaboration & feedback','Connect around a defined project or activity and bring practical feedback into the conversation.'),card('Business opportunities','Discuss introductions, subscription recommendations, services or resale under agreed commercial terms.')])+note('Benefits vary by route and agreement. Expressing interest does not automatically grant access, funding, partner status, publication, leads or earnings.'))+
section('choose-your-route','07 / FOLLOW THE ACTIVITY','Which route fits what you want to do?',table(['I want to','Suggested route'],[
['Create a tool or reusable geospatial workflow',link('Contributors','#contributors')],['Teach, research, run a workshop or explore an academic project',link('Education & Research','#education-research')],['Share expertise, mentor or engage a community',link('Ambassador','#community-growth')],['Recommend GriidAI through content and tracked links',link('Affiliate','#community-growth')],['Introduce an organization with a relevant business need',link('Referral Partner','#community-growth')],['Implement, integrate, train or support customer use',link('Solution delivery','#solutions-resellers')],['Manage subscription sales and the local commercial relationship',link('Reseller','#solutions-resellers')]
])+link('Help Me Choose',interest('help_me_choose')),{pale:true,intro:'Start with the activity you want to pursue. You can select more than one named path or ask us to help you choose.'})+
section('how-to-join','08 / A CLEAR NEXT STEP','Start with a conversation',stepper([['Express interest','Share your background, selected paths and a brief description of your idea or goals.'],['Discuss the fit','The team reviews the inquiry and follows up about the relevant opportunity and any further information needed.'],['Agree the scope','Clarify responsibilities, available support, requirements and any applicable terms.'],['Begin the activity','Move into the agreed contribution review, collaboration or onboarding process.']])+note('Submitting the form expresses interest. It does not confirm acceptance into a program.'))+
section('ecosystem-faq','ECOSYSTEM QUESTIONS','Find the path that fits your contribution',faq(faqs.ecosystem),{pale:true})+
finalCTA('express-interest','Tell us how you would like to participate.','Bring your expertise, community, ideas or customer experience. Share what you have in mind and explore the right way to work with GriidAI.',button('Express Interest',interest()));}

function enterprisePage(){return hero('Enterprise','Scale geospatial analysis with expert control built in.','GriidAi helps enterprise teams turn repeated spatial questions into inspectable, human-reviewed analysis workflows across geospatial data, supported GIS tools, maps and outputs—while keeping experts responsible for methodology, validation and the final decision.',contact()+button('See How GriidAi Works','/platform/',false),productFigure('A connected workspace for the question, analytical method and mapped output.'),'ENTERPRISE / REPEATED QUESTIONS. RETAINED METHODS.')+
jump([['The operating model','enterprise-model'],['Expert control','enterprise-control'],['Data & integration','enterprise-data'],['Requirements','enterprise-requirements'],['Pilot path','enterprise-pilot'],['FAQs','enterprise-faq']])+
section('enterprise-definition','A WORKFLOW ENVIRONMENT FOR TEAMS','What is GriidAi for enterprise geospatial teams?',`<div class="hub-reading">${paragraphs('GriidAi is an AI-guided geospatial workflow environment for organizations that want to make spatial analysis more inspectable, consistent and reusable. Bring relevant data into a workspace, ask a spatial question, review the proposed plan, run supported GIS operations, and validate maps and analytical outputs. Retain successful methods for repeated use where workflow functionality and organizational controls support it.')}</div>`)+
section('enterprise-challenge','01 / WHERE THE WORK REPEATS','Make repeated spatial work build organizational capability.',grid([card('Rework','Similar questions trigger repeated preparation, analysis setup and output production. Standardize analytical patterns where the method is proven.','','01'),card('Rare expertise','GIS, data, programming and validation knowledge sit across a small number of specialists. Assist execution while experts retain control.','','02'),card('Reuse gap','Methods and assumptions stay in project files or individual memory. Keep the review logic visible alongside the output.','','03'),card('Response delay','Decision-makers wait for technical work to become understandable evidence. Connect the question, method, map and handoff.','','04')],2),{pale:true})+
section('enterprise-model','02 / A REPEATABLE OPERATING MODEL','From a question to spatial evidence your experts can review',stepper(standardSteps))+
section('enterprise-control','03 / EXPERT CONTROL','AI proposes the work. Your experts control what proceeds.',reliability()+`<div class="actions">${contact('Discuss Your Workflow')}</div>`,{pale:true})+
section('enterprise-methods','04 / KEEP THE METHOD','Keep more of the method—not just the final map.',`<div class="hub-reading">${paragraphs(['The value of a successful geospatial workflow is not only the immediate result. Retain the data choices, analytical logic, assumptions and validation pattern so similar future questions do not start from zero.','Standardize repeated spatial analysis around reviewed methods, and retain analytical patterns for reuse where supported. The current workflow and data context determine what can be carried forward.'])}${link('Explore Workflow Examples','/workflows/')}</div>`)+
section('enterprise-data','05 / DATA & INTEGRATION','Work with the spatial data already relevant to the question.',`${paragraphs('GriidAi supports session-based work with uploaded vector, raster and tabular data, map layers, AOIs, attributes and metadata. Reference actual workspace layers in the next question, inspect spatial context and choose supported analytical outputs.')}${grid([card('Bring project data','Use supported file-based inputs and inspect the data before analysis.',link('Bring Your Own Data','/data/#bring-your-data')),card('Inspect workspace context','Review layers, attributes, study area and available metadata so similarly named files do not cause ambiguity.',link('Explore the Workspace','/platform/#workspace')),card('Discuss integration needs','Database connections, APIs and enterprise-specific integrations require a discussion of the current implementation and your requirements.',contact('Discuss Integration','Enterprise integrations'))])}${note('File support is separate from a live PostGIS, Oracle Spatial or MySQL connection. No database or API availability is inferred from an upload format.')}`,{pale:true})+
section('enterprise-requirements','06 / QUALIFY THE REQUIREMENTS','Scope security, deployment and governance around your needs.',`<div class="hub-split"><div>${paragraphs('Review security, access, data handling, deployment and governance requirements during enterprise qualification. Ask the team for current documentation and discuss the controls and deployment options relevant to your intended use.')}<div class="actions">${contact('Discuss Enterprise Requirements','Security and deployment')}</div></div><div class="hub-requirements"><span class="eyebrow">TOPICS TO DISCUSS</span><ul><li>Identity and access requirements</li><li>Data handling, retention and hosting</li><li>Deployment and networking needs</li><li>Integration and supported operations</li><li>Service, support and procurement expectations</li></ul><p class="hub-small">Availability and commitments depend on current documentation and the agreed scope.</p></div></div>`)+
section('enterprise-domains','07 / DOMAIN DECISIONS','Enterprise value starts with a concrete spatial question.',industryLinks(),{pale:true})+
section('enterprise-outputs','08 / OUTPUTS & HANDOFF','Return spatial evidence that can move into the next step.',grid([card('Maps & analytical layers','Review the spatial relationship and carry supported vector or raster outputs into another analytical process.'),card('Tables & statistics','Inspect selected features, derived fields and summaries with their assumptions and source context.'),card('Intermediate results & methods','Use intermediate outputs to inspect the sequence, and preserve useful method context for later work where supported.')])+link('Explore Spatial Analysis','/spatial-analysis/'))+
section('enterprise-fit','09 / FIT YOUR EXISTING WORK','Add a connected analysis layer around existing data and decisions.',`<div class="hub-reading">${paragraphs('Use GriidAi to connect spatial questions, supported GIS operations and expert review around your current processes. Evaluate it alongside desktop GIS, enterprise portals, databases and specialist models. Domain experts remain responsible for regulated, scientific and engineering interpretation.')}${link('See the Platform','/platform/')}</div>`,{pale:true})+
section('enterprise-pilot','10 / A SCOPED PILOT','Start with one repeatable spatial decision, then prove the operating model.',stepper([['Select the workflow','Choose a bounded, repeated question with a clear owner, intended users and expected output.'],['Confirm data & method','Review data readiness, supported operations and validation expectations.'],['Run the pilot','Execute with expert checkpoints and observe effort, failure handling and results.'],['Validate outputs','Compare with accepted practice or known outcomes; assess fit for purpose.'],['Assess repeatability','Check reuse, maintenance needs and the effort needed for another run.'],['Scope enterprise needs','Document integration, security, deployment and commercial requirements.']])+`<div class="actions">${contact('Plan an Enterprise Pilot','Enterprise workflow pilot')}</div>`)+
section('enterprise-roles','11 / CONNECT THE TEAM','A clear role for each kind of expertise',grid([card('GIS & geospatial managers','Reduce repeated setup while keeping GIS expertise inside the method.'),card('Domain experts','Define the decision and validate whether the result is fit for use.'),card('Data & platform leads','Understand sources, data context and the integration required.'),card('Innovation leaders','Test a bounded AI + GIS operating model before scaling.'),card('Asset, risk & operations leaders','Receive clearer spatial evidence with expert accountability.'),card('Security & procurement','Evaluate documented controls, deployment requirements and agreed commitments.')]),{pale:true})+
section('enterprise-faq','ENTERPRISE QUESTIONS','Evaluate the workflow before you scale',faq([
['How does GriidAi keep experts in control?','For supported tasks, users inspect Inputs, Method, Validation and Output before approving execution. After processing, the responsible expert validates the result and decides whether to use, adjust or rerun it.'],
['Can we use our own geospatial data?','Use supported file uploads and workspace layers. Review format handling, CRS, units, extent and the chosen operation; discuss database or other integration requirements separately.'],
['Can we standardize repeated analysis?','Begin with a reviewed method for one recurring question. Assess current reuse functionality and session behavior during a pilot before defining wider organizational controls.'],
['Are database connectors and APIs available?','Discuss the required database, interface, authentication and support boundaries with the team. File import does not establish a live database connection or a documented API.'],
['Can we discuss SSO, private cloud or data residency?','Yes. Bring your security, identity, hosting and governance requirements to qualification. Request current documentation; specific availability and commitments must be confirmed for your intended use.'],
['How should an enterprise evaluate GriidAi?','Choose a bounded, repeated workflow with measurable success criteria. Confirm data and method, run it with expert review, validate outputs and assess repeatability before scoping broader integration or deployment.']
]))+
finalCTA('enterprise-next-step','Prove the workflow. Then plan the scale.','Bring one recurring spatial question and the requirements your organization needs to evaluate.',contact()+button('Start for Free','https://app.griidai.com',false));}

function interestFormPage(){const choices=[['contributors','Contributors',['Tools','Reusable workflows','Documentation','Other contribution']],['education_research','Education & Research',['Teaching or training','Research','Student project','Institutional collaboration']],['community_growth','Community & Growth',['Ambassador','Affiliate','Referral Partner']],['solutions_resellers','Solution & Reseller',['Solution delivery','Reseller']]];
const field=(id,label,type='text',required=false,attrs='')=>`<div class="hub-field"><label for="${id}">${label}${required?' <span aria-hidden="true">*</span>':''}</label><input type="${type}" id="${id}" name="${id}" ${required?'required ':''}${attrs}></div>`;
return hero('Express Interest','Express interest in the GriidAI ecosystem','Tell us a little about yourself and how you would like to participate. Select one or more interests, or choose Help me choose.',link('Return to the Ecosystem','/ecosystem/'),`<aside class="hub-form-intro"><span class="eyebrow">A CONVERSATION, NOT A COMMITMENT</span><p>This form does not confirm program acceptance or commit you to a partnership.</p><p>Please do not include confidential customer information, proprietary code or sensitive documents.</p></aside>`,'ECOSYSTEM / EXPRESS INTEREST')+
`<section class="hub-section pale"><div class="container hub-form-layout"><div><span class="eyebrow">YOUR EXPERIENCE. YOUR IDEA.</span><h2>Tell us what you have in mind.</h2><p>Required fields are marked with an asterisk. No account, payment details or attachments are needed.</p>${link('Prefer to contact sales?','/contact-sales.html')}</div><form id="ecosystem-interest-form" class="hub-interest-form" data-endpoint="https://script.google.com/macros/s/AKfycbwl36CRPJ8PA6PSJtMWOeWT6SA_4zq3S98WHrvecIyUMBMo-Kd5eWD63d_TUYvtH4flxw/exec"><fieldset><legend>01 / About you</legend><div class="hub-form-grid">${field('full_name','Full name','text',true,'autocomplete="name" maxlength="150"')}${field('email','Email address','email',true,'autocomplete="email" maxlength="254"')}<div class="hub-field"><label for="participant_type">I am expressing interest as *</label><select id="participant_type" name="participant_type" required><option value="">Choose an option</option><option value="individual">Individual</option><option value="organization">Organization or institution</option></select></div>${field('organization','Organization or institution','text',false,'autocomplete="organization" maxlength="200"')}${field('role','Role or area of work','text',false,'autocomplete="organization-title" maxlength="150"')}${field('country','Country or region','text',true,'autocomplete="country-name" list="country-options" maxlength="100"')}<datalist id="country-options"></datalist></div></fieldset><fieldset id="interest-paths"><legend>02 / Which paths interest you? *</legend><p class="hub-small" id="path-help">Select multiple named paths, or choose Help me choose.</p><div class="hub-path-checkboxes">${choices.map(([value,label])=>`<label><input type="checkbox" name="paths" value="${value}" aria-describedby="path-help"><span>${label}</span></label>`).join('')}<label><input type="checkbox" name="paths" value="help_me_choose" aria-describedby="path-help"><span>Help me choose</span></label></div><p class="hub-small" id="path-status" aria-live="polite"></p>${choices.map(([value,label,interests])=>`<fieldset class="hub-specific-interests" data-path="${value}" hidden disabled><legend>${label} — specific interests (optional)</legend>${interests.map(i=>`<label><input type="checkbox" name="interests" value="${i.toLowerCase().replace(/[^a-z]+/g,'_')}"><span>${i}</span></label>`).join('')}</fieldset>`).join('')}</fieldset><fieldset><legend>03 / Your idea</legend><div class="hub-field"><label for="message">What would you like to contribute or achieve? *</label><textarea id="message" name="message" rows="6" maxlength="2000" required aria-describedby="message-count"></textarea><span class="hub-small" id="message-count">0 / 2,000 characters</span></div>${field('profile_url','Website or relevant work','url',false,'placeholder="https://example.com" maxlength="500"')}</fieldset><fieldset><legend>04 / Permission to respond</legend><label class="hub-consent"><input name="contact_consent" type="checkbox" required><span>I agree that GriidAI may contact me about this expression of interest. I have read the <a href="https://docs.griidai.com/docs/terms/#6-privacy-policy-and-data-use" target="_blank" rel="noopener noreferrer">Privacy Notice</a>.</span></label></fieldset><div class="hub-honeypot" aria-hidden="true"><label for="company_website">Leave this field empty</label><input id="company_website" name="company_website" tabindex="-1" autocomplete="off"></div><div id="interest-status" class="hub-form-status" role="status" tabindex="-1" hidden></div><button type="submit" class="button primary" id="interest-submit">Send Expression of Interest</button><p class="hub-small hub-form-transport-note">The contact service cannot confirm receipt in this browser. If delivery is not confirmed, your answers remain available and you can contact us directly.</p><noscript><p>Enable JavaScript to send this form, or email <a href="mailto:contact@griidai.com">contact@griidai.com</a>.</p></noscript></form></div></section>`;}

const pages=[
['data','Data | Geospatial Sources, Files & Workspace | GriidAi','Bring your own geospatial data or explore source access, format handling, workspace inspection and reviewed spatial analysis in GriidAi.',dataPage],
['industries','Industries | Geospatial Workflows for AEC, Climate, Utilities & Location Intelligence | GriidAi','Explore geospatial workflows for AEC and environmental consulting, climate resilience, utilities and critical infrastructure, and location intelligence.',industriesPage],
['use-cases','Geospatial Use Cases | Site Selection, Coverage, Climate, Hydrology & NDVI | GriidAi','Explore geospatial use cases for site selection, coverage gaps, flood and coastal risk, hydrology and vegetation analysis, with data, methods, review and outputs.',useCasesPage],
['workflows','GIS Workflow Automation & Geospatial Workflows | GriidAi','Explore GriidAi workflow examples for hydrology, NDVI, service coverage, sea-level rise and storm surge, with inspectable steps, human review and outputs.',workflowsPage],
['ecosystem','GriidAI Partner Ecosystem | Contribute, Educate and Grow','Explore the GriidAI ecosystem for contributors, education and research, community growth, solution delivery and reselling. Find your path and express interest.',ecosystemPage],
['enterprise','Enterprise Geospatial Workflows & AI-Guided Spatial Analysis | GriidAi','Standardize repeated geospatial analysis with inspectable plans, expert review, supported GIS workflows and enterprise evaluation paths in GriidAi.',enterprisePage],
['ecosystem/express-interest','Express Interest in the GriidAI Ecosystem','Tell the GriidAI team about your contribution, education, community or customer-facing partnership interests.',interestFormPage]
];
for(const [route,title,description,render] of pages){const name=route==='use-cases'?'Use Cases':route==='ecosystem/express-interest'?'Express Interest':route[0].toUpperCase()+route.slice(1);const url=origin+'/'+route+'/';const schema={'@context':'https://schema.org','@graph':[{'@type':['industries','use-cases','workflows'].includes(route)?'CollectionPage':'WebPage',name:title,url,description},{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:origin+'/'},{'@type':'ListItem',position:2,name,item:url}]}]};
if(route==='workflows')schema['@graph'].push({'@type':'ItemList',itemListElement:workflows.map((w,i)=>({'@type':'ListItem',position:i+1,name:w.name,url:url+'#'+w.id}))});
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${route.includes('express-interest')?'noindex,follow':'index,follow'}"><link rel="canonical" href="${url}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="${url}"><meta property="og:image" content="${origin}/assets/homepage-video-poster-1280.webp"><link rel="icon" type="image/png" sizes="180x180" href="/assets/griidai-icon.png"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/site-shell.css"><link rel="stylesheet" href="/hubs.css"><script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script><script src="/app.js" defer></script><script src="/hubs.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>${header('/'+route+'/')}<main id="main" class="hub-page hub-${route.split('/')[0]}">${render()}</main>${footer()}</body></html>`;
const dir=path.join(root,route);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),html.replace('src="/app.js"','src="/site-navigation.js"').replace('</head>',(route==='data'?'<link rel="stylesheet" href="/data-gallery.css"><script src="/data-gallery.js" defer></script>':'')+'</head>')+'\n');}
// Apply the same navigation and footer to the existing site, without changing
// legacy content anchors or replacing page-specific layouts.
for(const route of ['','platform','agentic-geoai','spatial-analysis','solutions','about','pricing','contact-sales.html']){
const file=route.endsWith('.html')?path.join(root,route):path.join(root,route,'index.html');let html=fs.readFileSync(file,'utf8');
html=html.replace(/<header[\s>][\s\S]*?<\/header>/,header(route.endsWith('.html')?'/'+route:'/'+(route?route+'/':'')));
html=html.replace(/<footer[\s>][\s\S]*?<\/footer>/,footer());
html=html.replace('src="/app.js"','src="/site-navigation.js"');
if(route==='contact-sales.html'&&!html.includes('id="main"'))html=html.replace('<body>','<body id="main">');
if(!html.includes('href="/site-shell.css"'))html=html.replace('</head>','<link rel="stylesheet" href="/site-shell.css"></head>');
html=html.replace(/href="#detail" data-workflow="(\d+)"/g,(_,n)=>`href="/workflows/#${workflows[Number(n)].id}"`);
html=html.replace(/<a([^>]*?)class="modal-link"([^>]*?)href="[^"]*"/g,'<a$1class="ecosystem-link"$2href="/ecosystem/"');
html=html.replace(/<a([^>]*?)href="[^"]*"([^>]*?)class="modal-link"/g,'<a$1href="/ecosystem/"$2class="ecosystem-link"');
html=html.replace(/<a\b[^>]*\bclass="[^"]*\bmodal-link\b[^"]*"[^>]*>/g,tag=>tag.replace(/\bhref="[^"]*"/,'href="/ecosystem/"').replace(/\bmodal-link\b/,'ecosystem-link'));
html=html.replaceAll('href="/#data"','href="/data/"').replaceAll('href="/solutions/#industries"','href="/industries/"').replaceAll('href="/solutions/#use-cases"','href="/use-cases/"');
fs.writeFileSync(file,html);}
const sitemap=pages.filter(([r])=>!r.includes('express-interest')).map(([r])=>`<url><loc>${origin}/${r}/</loc></url>`).join('');
fs.writeFileSync(path.join(root,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemap}</urlset>\n`);
console.log('Generated six content hubs, ecosystem intake, and shared navigation.');
